 Contract setupAccounts(String annual,String sick,String hospital){return setupAccounts(annual,sick,hospital,LocalDate.of(2026,11,1));}
 Contract setupAccounts(String annual,String sick,String hospital,LocalDate contractEffectiveFrom){var ref=ComplianceReference.singapore();var p=compliance.savePolicy(admin,store,UUID.randomUUID(),new PolicyWrite(0L,"Reviewed SG policy",LocalDate.of(2026,1,1),LocalDate.of(2028,12,31),true,ref.rules(),ref.sources()));var c=compliance.saveContract(admin,store,employee,UUID.randomUUID(),new ContractWrite(0L,contractEffectiveFrom,LocalDate.of(2026,1,1),p.id(),1L,n("8"),n("40"),n("5"),n("8"),n("44"),"workman","Signed synthetic contract reviewed"));accountService.enable(admin,store,UUID.randomUUID(),new Enable(employee,2026,c.id(),LocalDate.of(2026,11,1),List.of(new Opening("annual",n(annual)),new Opening("sick",n(sick)),new Opening("hospital",n(hospital))),"Opening remaining balance reconciled through 1 November"));return c;}
