 @Test void existingLeaveApprovalReservesUsesAndCancelsWithoutErasingHistory(){setupAccounts("2","14","60");var type=type("annual");var day=day(2);var id=UUID.randomUUID();var command=new LeaveDtos.LeaveWrite(day.id(),type,day.startAt(),day.endAt(),"Synthetic annual leave");var l=managedLeaves.submit(worker,store,id,command);assertThat(managedLeaves.submit(worker,store,id,command)).isEqualTo(l);assertThat(balance("annual",2026).available()).isEqualByComparingTo("1");assertThat(balance("annual",2026).reserved()).isEqualByComparingTo("1");managedLeaves.decide(admin,store,id,new com.rpb.reservation.workforce.attendance.AttendanceDtos.DecisionWrite(1L,"approved","Reviewed"));assertThat(balance("annual",2026).used()).isEqualByComparingTo("1");assertThat(balance("annual",2026).reserved()).isZero();managedLeaves.decide(worker,store,id,new com.rpb.reservation.workforce.attendance.AttendanceDtos.DecisionWrite(2L,"cancel_requested","Change plans"));assertThat(balance("annual",2026).available()).isEqualByComparingTo("1");managedLeaves.decide(admin,store,id,new com.rpb.reservation.workforce.attendance.AttendanceDtos.DecisionWrite(3L,"cancelled","Cancellation reviewed"));assertThat(balance("annual",2026).available()).isEqualByComparingTo("2");assertThat(balance("annual",2026).history()).extracting(Entry::operation).containsExactly("use","cancel-use");}
 @Test void insufficientLeaveRollsBackBothApplicationAndReservations(){setupAccounts("1","14","60");var type=type("annual");var first=day(2);managedLeaves.submit(worker,store,UUID.randomUUID(),new LeaveDtos.LeaveWrite(first.id(),type,first.startAt(),first.endAt(),"First"));var second=day(3);UUID failed=UUID.randomUUID();assertThatThrownBy(()->managedLeaves.submit(worker,store,failed,new LeaveDtos.LeaveWrite(second.id(),type,second.startAt(),second.endAt(),"Second"))).hasMessage("LEAVE_BALANCE_INSUFFICIENT");assertThat(new LeaveRepository(jdbc).find(tenant,failed)).isEmpty();assertThat(accounts.holds(tenant,failed)).isEmpty();assertThat(balance("annual",2026).available()).isZero();}
 @Test void sickLeaveAlsoReservesSharedHospitalCap(){setupAccounts("2","2","1");var type=type("sick");var first=day(2);managedLeaves.submit(worker,store,UUID.randomUUID(),new LeaveDtos.LeaveWrite(first.id(),type,first.startAt(),first.endAt(),"Certified sick leave"));assertThat(balance("hospital",2026).available()).isZero();var second=day(3);UUID failed=UUID.randomUUID();assertThatThrownBy(()->managedLeaves.submit(worker,store,failed,new LeaveDtos.LeaveWrite(second.id(),type,second.startAt(),second.endAt(),"Second MC"))).hasMessage("LEAVE_BALANCE_INSUFFICIENT");assertThat(accounts.holds(tenant,failed)).isEmpty();}
 @Test void annualRolloverIsIdempotentAndDoesNotRefreshOldExpiry(){setupAccounts("2","14","60");time.at("2027-01-01T00:00:00Z");var id=UUID.randomUUID();var c=new YearEnd(employee,2026,"Calendar close reviewed");var next=years.close(admin,store,id,c);assertThat(years.close(admin,store,id,c)).isEqualTo(next);assertThat(balance("annual",2027).lots().stream().filter(l->l.origin().equals("carry"))).allMatch(l->l.expiresOn().equals(LocalDate.of(2027,12,31)));var before=balance("annual",2027).available();years.close(admin,store,UUID.randomUUID(),c);assertThat(balance("annual",2027).available()).isEqualByComparingTo(before);assertThat(balance("annual",2026).lots()).allMatch(l->l.remaining().signum()==0);}

 @Test void reviewedBalanceKeepsAccruedButUnpostedUnits(){var contract=setupAccounts("2","14","60");time.at("2026-12-31T00:00:00Z");var b=balance("annual",2026);assertThat(b.dueAccrual()).isPositive();accountService.review(admin,store,UUID.randomUUID(),new Review(employee,b.account().id(),b.account().version(),contract.id(),LocalDate.of(2026,12,31),b.available(),"Reviewed earned balance without losing pending accrual"));assertThat(balance("annual",2026).available()).isEqualByComparingTo(b.available());assertThat(balance("annual",2026).dueAccrual()).isZero();}
 @Test void concurrentRequestsCannotOverspendOneRemainingDay()throws Exception{setupAccounts("1","14","60");var type=type("annual");var first=day(2);var second=day(3);var start=new java.util.concurrent.CountDownLatch(1);var pool=java.util.concurrent.Executors.newFixedThreadPool(2);try{var results=new java.util.ArrayList<java.util.concurrent.Future<Boolean>>();for(var s:List.of(first,second))results.add(pool.submit(()->{start.await();try{managedLeaves.submit(worker,store,UUID.randomUUID(),new LeaveDtos.LeaveWrite(s.id(),type,s.startAt(),s.endAt(),"Concurrent test"));return true;}catch(com.rpb.reservation.workforce.domain.WorkforceException ex){assertThat(ex.code()).isEqualTo("LEAVE_BALANCE_INSUFFICIENT");return false;}}));start.countDown();int ok=0;for(var r:results)if(r.get(20,java.util.concurrent.TimeUnit.SECONDS))ok++;assertThat(ok).isEqualTo(1);assertThat(balance("annual",2026).available()).isZero();assertThat(balance("annual",2026).reserved()).isEqualByComparingTo("1");}finally{pool.shutdownNow();}}
 @Test void medicalLeaveNeedsExplicitEvidenceAndCannotBypassSharedCap(){setupAccounts("2","2","2");var type=type("sick");var s=day(2);var l=managedLeaves.submit(worker,store,UUID.randomUUID(),new LeaveDtos.LeaveWrite(s.id(),type,s.startAt(),s.endAt(),"Sick request"));assertThatThrownBy(()->managedLeaves.decide(admin,store,l.id(),new com.rpb.reservation.workforce.attendance.AttendanceDtos.DecisionWrite(1L,"approved","Reviewed"))).hasMessage("LEAVE_MEDICAL_EVIDENCE_REQUIRED");assertThat(new LeaveRepository(jdbc).find(tenant,l.id()).orElseThrow().status()).isEqualTo("pending");managedLeaves.decide(worker,store,l.id(),new com.rpb.reservation.workforce.attendance.AttendanceDtos.DecisionWrite(1L,"withdrawn","Replace with certified request"));var certified=managedLeaves.submit(worker,store,UUID.randomUUID(),new LeaveDtos.LeaveWrite(s.id(),type,s.startAt(),s.endAt(),"Certified sick request","Synthetic MC reviewed, covers requested date"));managedLeaves.decide(admin,store,certified.id(),new com.rpb.reservation.workforce.attendance.AttendanceDtos.DecisionWrite(1L,"approved","MC dates checked"));assertThat(balance("sick",2026).used()).isEqualByComparingTo("1");assertThat(balance("hospital",2026).used()).isEqualByComparingTo("1");}
 @Test void sameYearEmployerTransferOpensIndependentBankAndKeepsPriorEmployerReadOnly(){var original=setupAccounts("2","14","60");var old=balance("annual",2026);var originalType=type("annual");var oldDay=day(3);managedLeaves.submit(worker,store,UUID.randomUUID(),new LeaveDtos.LeaveWrite(oldDay.id(),originalType,oldDay.startAt(),oldDay.endAt(),"Prior employer pending leave"));var e=repository.find(tenant,employee).orElseThrow();time.at("2026-11-02T00:00:00Z");var editable=proxy(new WorkforceEmployeeService(access,directory,repository,new com.rpb.reservation.auth.application.WorkforceAccountProvisioner(jdbc,new org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder()),new WorkforceAudit(logs,new ObjectMapper().findAndRegisterModules()),time,new com.rpb.reservation.workforce.positions.EmployeePositionSelection(new com.rpb.reservation.workforce.positions.PositionRepository(jdbc))));editable.save(admin,store,employee,new WorkforceDtos.EmployeeWrite(e.version(),e.employeeNo(),e.name(),e.phone(),e.email(),e.jobTitle(),e.hireDate(),null,"active",otherCompany,LocalDate.of(2026,11,2),store,List.of(store,sibling),e.accountId(),null,null));var next=compliance.saveContract(admin,store,employee,UUID.randomUUID(),new ContractWrite(original.version(),LocalDate.of(2026,11,2),LocalDate.of(2026,11,2),original.policyId(),original.policyVersion(),n("8"),n("40"),n("5"),n("8"),n("44"),"workman","Independent new employer contract, no service transfer"));accountService.enable(admin,store,UUID.randomUUID(),new Enable(employee,2026,next.id(),LocalDate.of(2026,11,2),List.of(new Opening("annual",n("1"))),"Reviewed new employer grant, no old balance copied"));var records=accounts.accounts(tenant,employee,2026);assertThat(records.stream().filter(a->a.companyId().equals(otherCompany))).hasSize(1);assertThat(accounts.find(tenant,old.account().id()).orElseThrow().companyId()).isEqualTo(company);accountService.refresh(admin,store,UUID.randomUUID(),new Refresh(employee,2026,"Refresh current employer only"));assertThatThrownBy(()->accountService.adjust(admin,store,UUID.randomUUID(),new Adjust(employee,old.account().id(),old.account().version(),n("1"),LocalDate.of(2027,12,31),"Cannot adjust prior employer"))).isInstanceOf(com.rpb.reservation.workforce.domain.WorkforceException.class);assertThat(accounts.lots(tenant,old.account().id()).stream().map(Lot::remaining).reduce(BigDecimal.ZERO,BigDecimal::add)).isEqualByComparingTo("2");}
 @Test void overlappingApprovedLeaveCannotConsumeTheSameDayAgain(){setupAccounts("4","14","60");var type=type("annual");var day=day(2);var first=managedLeaves.submit(worker,store,UUID.randomUUID(),new LeaveDtos.LeaveWrite(day.id(),type,day.startAt(),day.endAt(),"First application"));managedLeaves.decide(admin,store,first.id(),new com.rpb.reservation.workforce.attendance.AttendanceDtos.DecisionWrite(1L,"approved","Reviewed"));var duplicate=UUID.randomUUID();assertThatThrownBy(()->managedLeaves.submit(worker,store,duplicate,new LeaveDtos.LeaveWrite(day.id(),type,day.startAt(),day.endAt(),"Overlapping application"))).hasMessage("WORKFORCE_LEAVE_OVERLAP");assertThat(new LeaveRepository(jdbc).find(tenant,duplicate)).isEmpty();assertThat(balance("annual",2026).used()).isEqualByComparingTo("1");assertThat(balance("annual",2026).available()).isEqualByComparingTo("3");}

 com.rpb.reservation.workforce.leave.entitlement.LeaveEntitlementService intervalEntitlements;
 com.rpb.reservation.workforce.attendance.daily.AttendanceExceptionService intervalService(){
  var json=new WorkforceJson(new ObjectMapper().findAndRegisterModules());var audit=new WorkforceAudit(logs,new ObjectMapper().findAndRegisterModules());
  var pr=new com.rpb.reservation.workforce.attendancepolicy.AttendancePolicyRepository(jdbc,json);var ar=new com.rpb.reservation.workforce.approval.ApprovalRepository(jdbc,json);var dr=new com.rpb.reservation.workforce.attendance.daily.AttendanceDailyRepository(jdbc,json);
  var resolver=new com.rpb.reservation.workforce.attendancepolicy.AttendancePolicyResolver(pr,repository,new com.rpb.reservation.workforce.workmode.WorkModeRepository(jdbc,json));
  var daily=new com.rpb.reservation.workforce.attendance.daily.AttendanceDailyService(resolver,pr,dr,schedules,null,ar,repository,access,json,audit,time);
  var manual=new com.rpb.reservation.workforce.leave.entitlement.LeaveEntitlementService(access,repository,new com.rpb.reservation.workforce.leave.entitlement.LeaveEntitlementRepository(jdbc,json),daily,audit,policies,accounts,balances);
  intervalEntitlements=proxy(manual);
  var intervalBridge=new IntervalLeaveAccountBridge(accounts,policies,balances,daily,new com.rpb.reservation.workforce.calendar.CalendarRepository(jdbc),manual,schedules);
  return proxy(new com.rpb.reservation.workforce.attendance.daily.AttendanceExceptionService(access,repository,schedules,pr,dr,new LeaveTypeRepository(jdbc),ar,audit,time,intervalBridge));
 }
 @Test void intervalAndScheduledLeaveUseOneBankAndFinalCancellationRestoresIt(){
  setupAccounts("1","14","60");var type=type("annual");var first=day(2);var second=day(3);var service=intervalService();var id=UUID.randomUUID();
  var command=new com.rpb.reservation.workforce.attendance.daily.AttendanceDailyDtos.ExceptionWrite(employee,company,first.workDate(),"leave",type,first.startAt(),first.endAt(),"Interval annual leave");
  var submitted=service.submit(worker,store,id,command);assertThat(service.submit(worker,store,id,command)).isEqualTo(submitted);
  assertThat(balance("annual",2026).reserved()).isEqualByComparingTo("1");
  assertThatThrownBy(()->managedLeaves.submit(worker,store,UUID.randomUUID(),new LeaveDtos.LeaveWrite(second.id(),type,second.startAt(),second.endAt(),"Same bank"))).hasMessage("LEAVE_BALANCE_INSUFFICIENT");
  service.decide(admin,store,id,new com.rpb.reservation.workforce.attendance.daily.AttendanceDailyDtos.DecisionWrite(1L,"approved","Reviewed"));
  assertThat(balance("annual",2026).used()).isEqualByComparingTo("1");
  service.decide(worker,store,id,new com.rpb.reservation.workforce.attendance.daily.AttendanceDailyDtos.DecisionWrite(2L,"cancel_requested","Cancel requested"));assertThat(balance("annual",2026).available()).isZero();
  service.decide(admin,store,id,new com.rpb.reservation.workforce.attendance.daily.AttendanceDailyDtos.DecisionWrite(3L,"cancelled","Reviewed cancellation"));assertThat(balance("annual",2026).available()).isEqualByComparingTo("1");
 }
 @Test void intervalMedicalReferencePersistsAndSharedHospitalCapIsConsumed(){
  setupAccounts("1","1","1");var type=type("sick");var s=day(2);var service=intervalService();var id=UUID.randomUUID();
  var request=new com.rpb.reservation.workforce.attendance.daily.AttendanceDailyDtos.ExceptionWrite(employee,company,s.workDate(),"leave",type,s.startAt(),s.endAt(),"Medical leave","MC-REF-001");
  var submitted=service.submit(worker,store,id,request);assertThat(submitted.medicalReference()).isEqualTo("MC-REF-001");
  service.decide(admin,store,id,new com.rpb.reservation.workforce.attendance.daily.AttendanceDailyDtos.DecisionWrite(1L,"approved","MC reference reviewed"));
  assertThat(balance("sick",2026).used()).isEqualByComparingTo("1");assertThat(balance("hospital",2026).used()).isEqualByComparingTo("1");
 }

 @Test void concurrentIntervalAndScheduledRequestsCannotOverspendSameBank()throws Exception{
  setupAccounts("1","14","60");var type=type("annual");var first=day(2);var second=day(3);var service=intervalService();var latch=new java.util.concurrent.CountDownLatch(1);var pool=java.util.concurrent.Executors.newFixedThreadPool(2);
  try{
   var a=pool.submit(()->{latch.await();try{service.submit(worker,store,UUID.randomUUID(),new com.rpb.reservation.workforce.attendance.daily.AttendanceDailyDtos.ExceptionWrite(employee,company,first.workDate(),"leave",type,first.startAt(),first.endAt(),"Concurrent interval"));return true;}catch(com.rpb.reservation.workforce.domain.WorkforceException ex){assertThat(ex.code()).isEqualTo("LEAVE_BALANCE_INSUFFICIENT");return false;}});
   var b=pool.submit(()->{latch.await();try{managedLeaves.submit(worker,store,UUID.randomUUID(),new LeaveDtos.LeaveWrite(second.id(),type,second.startAt(),second.endAt(),"Concurrent scheduled"));return true;}catch(com.rpb.reservation.workforce.domain.WorkforceException ex){assertThat(ex.code()).isEqualTo("LEAVE_BALANCE_INSUFFICIENT");return false;}});
   latch.countDown();assertThat(List.of(a.get(20,java.util.concurrent.TimeUnit.SECONDS),b.get(20,java.util.concurrent.TimeUnit.SECONDS))).containsExactlyInAnyOrder(true,false);assertThat(balance("annual",2026).available()).isZero();assertThat(balance("annual",2026).reserved()).isEqualByComparingTo("1");
  }finally{pool.shutdownNow();}
 }

 @Test void canonicalBalanceSupersedesManualGrantWithoutDeletingHistory(){
  var type=type("annual");intervalService();
  var request=new com.rpb.reservation.workforce.leave.entitlement.LeaveEntitlementDtos.Write(0L,company,type,2026,n("100"),BigDecimal.ZERO,BigDecimal.ZERO,"HOURS",null,"Explicit legacy manual allowance");
  intervalEntitlements.save(admin,store,employee,UUID.randomUUID(),request);
  setupAccounts("2","14","60");
  var row=intervalEntitlements.page(admin,store,employee,2026,company).balances().stream().filter(b->b.typeId().equals(type)).findFirst().orElseThrow();
  assertThat(row.remaining()).isEqualByComparingTo("2");assertThat(row.accountUnit()).isEqualTo("DAYS");assertThat(row.policy()).isNull();assertThat(row.unknownReasons()).contains("CANONICAL_LEAVE_ACCOUNT");
  assertThatThrownBy(()->intervalEntitlements.save(admin,store,employee,UUID.randomUUID(),new com.rpb.reservation.workforce.leave.entitlement.LeaveEntitlementDtos.Write(1L,company,type,2026,n("200"),BigDecimal.ZERO,BigDecimal.ZERO,"HOURS",null,"Do not double grant"))).hasMessage("LEAVE_CANONICAL_ACCOUNT_REQUIRED");
  assertThat(jdbc.queryForObject("select count(*) from workforce_leave_entitlements where tenant_id=? and employee_id=?",Integer.class,tenant,employee)).isEqualTo(1);
 }
